/bin/bash -lc "cat <<'EOF' > lib/catalog.ts
import { cacheTag } from 'next/cache';
import { getAllProducts } from './db';

export type CatalogProduct = {
  id: string;
  sku: string;
  name: string;
  price: number;
  inventory: number;
  status: 'In Stock' | 'Low Stock' | 'Out of Stock';
  updatedAt: string;
};

export async function getCatalogProducts(): Promise<CatalogProduct[]> {
  'use cache';
  cacheTag('products');

  return getAllProducts();
}
EOF"

/bin/bash -lc "cat <<'EOF' > lib/sync.ts
export async function queueCatalogSync(): Promise<void> {
  // In production, enqueue a background job with your ERP/PIM integration.
  await new Promise(resolve => setTimeout(resolve, 10));
}
EOF"

/bin/bash -lc "cat <<'EOF' > app/page.tsx
import { revalidateTag } from 'next/cache';

import { getCatalogProducts } from '@/lib/catalog';
import { queueCatalogSync } from '@/lib/sync';

const currencyFormatter = new Intl.NumberFormat('en-US', {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
});

function formatCurrency(value: number) {
  return currencyFormatter.format(value);
}

export default async function Page() {
  const products = await getCatalogProducts();
  const totalSkus = products.length;
  const lowStock = products.filter(product => product.status === 'Low Stock').length;
  const outOfStock = products.filter(product => product.status === 'Out of Stock').length;
  const totalInventory = products.reduce((sum, product) => sum + product.inventory, 0);
  const inventoryValue = products.reduce(
    (sum, product) => sum + product.price * product.inventory,
    0
  );

  async function syncCatalogAction() {
    'use server';
    await queueCatalogSync();
    revalidateTag('products', 'max');
  }

  return (
    <main
      style={{
        fontFamily: '\"IBM Plex Sans\", system-ui, -apple-system, sans-serif',
        padding: '40px',
        color: '#0f172a',
        background: '#f8fafc',
        minHeight: '100vh',
      }}
    >
      <section
        style={{
          display: 'flex',
          flexWrap: 'wrap',
          alignItems: 'flex-start',
          justifyContent: 'space-between',
          gap: '24px',
          marginBottom: '32px',
        }}
      >
        <div>
          <p style={{ textTransform: 'uppercase', letterSpacing: '0.12em', fontSize: '12px' }}>
            Admin Catalog
          </p>
          <h1 style={{ fontSize: '32px', margin: '8px 0 12px' }}>Product Catalog</h1>
          <p style={{ maxWidth: '520px', margin: 0, color: '#475569' }}>
            Browse the latest product data with low-latency caching. When ERP or PIM data changes,
            trigger a background sync to refresh pricing, inventory, and availability across all
            catalog views.
          </p>
        </div>
        <form
          action={syncCatalogAction}
          style={{
            background: '#0f172a',
            color: 'white',
            padding: '20px',
            borderRadius: '16px',
            minWidth: '280px',
          }}
        >
          <h2 style={{ margin: '0 0 8px', fontSize: '16px' }}>Sync latest catalog</h2>
          <p style={{ margin: '0 0 16px', fontSize: '13px', color: '#cbd5f5' }}>
            Sync runs in the background. Cached data may appear briefly stale while refreshes
            propagate.
          </p>
          <button
            type=\"submit\"
            style={{
              width: '100%',
              padding: '10px 16px',
              borderRadius: '10px',
              border: 'none',
              fontWeight: 600,
              cursor: 'pointer',
              background: '#38bdf8',
              color: '#0f172a',
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </section>

      <section
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
          gap: '16px',
          marginBottom: '32px',
        }}
      >
        {[
          { label: 'Total SKUs', value: totalSkus },
          { label: 'Low stock', value: lowStock },
          { label: 'Out of stock', value: outOfStock },
          { label: 'On-hand units', value: totalInventory },
          { label: 'Inventory value', value: formatCurrency(inventoryValue) },
        ].map(card => (
          <div
            key={card.label}
            style={{
              background: 'white',
              padding: '16px',
              borderRadius: '14px',
              boxShadow: '0 10px 30px rgba(15, 23, 42, 0.08)',
            }}
          >
            <p style={{ margin: 0, fontSize: '12px', color: '#64748b' }}>{card.label}</p>
            <p style={{ margin: '8px 0 0', fontSize: '20px', fontWeight: 600 }}>{card.value}</p>
          </div>
        ))}
      </section>

      <section
        style={{
          background: 'white',
          borderRadius: '16px',
          padding: '20px',
          boxShadow: '0 12px 32px rgba(15, 23, 42, 0.08)',
        }}
      >
        <h2 style={{ margin: '0 0 16px' }}>Catalog snapshot</h2>
        <div style={{ overflowX: 'auto' }}>
          <table
            style={{
              width: '100%',
              borderCollapse: 'collapse',
              fontSize: '14px',
              minWidth: '720px',
            }}
          >
            <thead>
              <tr style={{ textAlign: 'left', borderBottom: '1px solid #e2e8f0' }}>
                <th style={{ paddingBottom: '12px' }}>SKU</th>
                <th style={{ paddingBottom: '12px' }}>Product</th>
                <th style={{ paddingBottom: '12px' }}>Price</th>
                <th style={{ paddingBottom: '12px' }}>Inventory</th>
                <th style={{ paddingBottom: '12px' }}>Status</th>
                <th style={{ paddingBottom: '12px' }}>Last updated</th>
              </tr>
            </thead>
            <tbody>
              {products.map(product => (
                <tr key={product.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                  <td style={{ padding: '12px 0', fontWeight: 600 }}>{product.sku}</td>
                  <td style={{ padding: '12px 0' }}>{product.name}</td>
                  <td style={{ padding: '12px 0' }}>{formatCurrency(product.price)}</td>
                  <td style={{ padding: '12px 0' }}>{product.inventory}</td>
                  <td style={{ padding: '12px 0' }}>
                    <span
                      style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        padding: '4px 10px',
                        borderRadius: '999px',
                        fontSize: '12px',
                        fontWeight: 600,
                        background:
                          product.status === 'In Stock'
                            ? '#dcfce7'
                            : product.status === 'Low Stock'
                            ? '#fef9c3'
                            : '#fee2e2',
                        color:
                          product.status === 'In Stock'
                            ? '#166534'
                            : product.status === 'Low Stock'
                            ? '#854d0e'
                            : '#b91c1c',
                      }}
                    >
                      {product.status}
                    </span>
                  </td>
                  <td style={{ padding: '12px 0', color: '#64748b' }}>
                    {product.updatedAt}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </main>
  );
}
EOF"
